WITH flattened_attrs AS (SELECT id, service, host, level, latency_ms, status_code, payload_json, COALESCE(context['trace'], 'direct') AS trace_or_default, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE service IN ('checkout', 'auth', 'search')) SELECT CASE WHEN latency_ms >= 2669 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, COUNT_IF(tier = 'pro') AS pro_events, COUNT(CASE WHEN tier = 'pro' THEN 1 END) AS pro_count, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN host = 'h1' THEN 1 END), 0), 2) AS latency_ms_per_h1, COUNT(DISTINCT tier) AS distinct_tiers FROM flattened_attrs GROUP BY latency_ms_tier HAVING COUNT(CASE WHEN tier = 'pro' THEN 1 END) >= 1
